export default {"P001009":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Ring homomorphisms · predicate · <code>P001009</code></p><h3>Étale local homomorphism in the Noetherian convention</h3><p>Let <span class=\"atlas-math\"><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>A</mi><mo>→</mo><mi>B</mi></mrow><annotation encoding=\"application/x-tex\">A\\to B</annotation></semantics></math></span></span> be a local homomorphism of Noetherian local rings. The map is flat and unramified in the local-ring sense of Tag 024M.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/0258\">Stacks 0258 · numbered source and proof · Stacks 0258 · common source definition · Stacks 0258 · étale local homomorphism</a> <a class=\"algebra-index-ref\" href=\"../topologies/database/stacks/etale/#tag-0258\">Index</a> · <a href=\"https://www.iut-theory.org/divers/ega44.pdf\">Grothendieck–Dieudonné, EGA IV₄, 17.6.1 and 17.6.3, local and completed étale criteria</a></p><p class=\"algebra-links\"><a href=\"../topologies/database/#P001009\">Open shared record</a></p></article>","P001008":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Ring homomorphisms · predicate · <code>P001008</code></p><h3>Finite separable residue extension of a local map</h3><p>For the specified local ring homomorphism the induced extension of residue fields is finite and separable.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/024M\">Stacks 024M · numbered source and proof · Stacks 024M · common source definition · Stacks 024M · (2)</a> <a class=\"algebra-index-ref\" href=\"../topologies/database/stacks/etale/#tag-024M\">Index</a></p><p class=\"algebra-links\"><a href=\"../topologies/database/#P001008\">Open shared record</a></p></article>","P001025":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Ring homomorphisms · predicate · <code>P001025</code></p><h3>Ring homomorphism with reduced source</h3><p>The source ring of the specified homomorphism is reduced.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/039U\">Stacks 039U · numbered source and proof</a> <a class=\"algebra-index-ref\" href=\"../topologies/database/stacks/etale/#tag-039U\">Index</a></p><p class=\"algebra-links\"><a href=\"../topologies/database/#P001025\">Open shared record</a></p></article>","P001026":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Ring homomorphisms · predicate · <code>P001026</code></p><h3>Ring homomorphism with reduced target</h3><p>The target ring of the specified homomorphism is reduced.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/039U\">Stacks 039U · numbered source and proof</a> <a class=\"algebra-index-ref\" href=\"../topologies/database/stacks/etale/#tag-039U\">Index</a></p><p class=\"algebra-links\"><a href=\"../topologies/database/#P001026\">Open shared record</a></p></article>","P001007":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Ring homomorphisms · predicate · <code>P001007</code></p><h3>Source maximal ideal generates the target maximal ideal</h3><p>For a local map <span class=\"atlas-math\"><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\">(</mo><mi>A</mi><mo separator=\"true\">,</mo><mi mathvariant=\"normal\">𝔪</mi><mo stretchy=\"false\">)</mo><mo>→</mo><mo stretchy=\"false\">(</mo><mi>B</mi><mo separator=\"true\">,</mo><mi mathvariant=\"normal\">𝔫</mi><mo stretchy=\"false\">)</mo></mrow><annotation encoding=\"application/x-tex\">(A,\\mathfrak m)\\to(B,\\mathfrak n)</annotation></semantics></math></span></span>, one has <span class=\"atlas-math\"><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">𝔪</mi><mi>B</mi><mo>=</mo><mi mathvariant=\"normal\">𝔫</mi></mrow><annotation encoding=\"application/x-tex\">\\mathfrak mB=\\mathfrak n</annotation></semantics></math></span></span>.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/024M\">Stacks 024M · numbered source and proof · Stacks 024M · common source definition · Stacks 024M · (1)</a> <a class=\"algebra-index-ref\" href=\"../topologies/database/stacks/etale/#tag-024M\">Index</a></p><p class=\"algebra-links\"><a href=\"../topologies/database/#P001007\">Open shared record</a></p></article>","P001006":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Ring homomorphisms · predicate · <code>P001006</code></p><h3>Unramified local homomorphism in the Noetherian convention</h3><p>Let <span class=\"atlas-math\"><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>A</mi><mo>→</mo><mi>B</mi></mrow><annotation encoding=\"application/x-tex\">A\\to B</annotation></semantics></math></span></span> be a local homomorphism of Noetherian local rings. The target is essentially of finite type, its maximal ideal is generated by the source maximal ideal, and its residue extension is finite separable. This definition concerns local rings; the unlocalized algebra need not be of finite type.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/024M\">Stacks 024M · numbered source and proof · Stacks 024M · common source definition · Stacks 024M · definition with (1)–(3)</a> <a class=\"algebra-index-ref\" href=\"../topologies/database/stacks/etale/#tag-024M\">Index</a> · <a href=\"https://www.iut-theory.org/divers/ega44.pdf\">Grothendieck–Dieudonné, EGA IV₄, 17.4.1 and 17.4.4, under the finite presentation or Noetherian hypotheses there</a> · <a href=\"https://stacks.math.columbia.edu/tag/0258\">Stacks 0258 · common source definition</a> <a class=\"algebra-index-ref\" href=\"../topologies/database/stacks/etale/#tag-0258\">Index</a></p><p class=\"algebra-links\"><a href=\"../topologies/database/#P001006\">Open shared record</a></p></article>"};
